package com.hmdp.ai.infrastructure.external;import com.fasterxml.jackson.databind.ObjectMapper;import com.hmdp.ai.domain.external.ExternalSearchGateway;import com.hmdp.ai.domain.run.*;import com.hmdp.ai.domain.security.AuthorizationContext;import com.hmdp.ai.domain.tool.*;import com.hmdp.ai.shared.id.AiIdGenerator;import org.junit.jupiter.api.Test;import java.time.Instant;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;
class ExternalSearchAdapterContractTest {@Test void reportsProviderNotConfiguredWithoutFabricatingResults(){ObjectMapper mapper=new ObjectMapper();ExternalSearchGateway gateway=(q,l,c)->{throw new IllegalArgumentException("PROVIDER_NOT_CONFIGURED");};ExternalSearchToolProtocolAdapter adapter=new ExternalSearchToolProtocolAdapter(gateway,mapper,new AiIdGenerator());ToolResult result=adapter.execute(tool(),new ToolInvocation("call","search",1,context(),mapper.createObjectNode().put("query","shops")),mapper.createObjectNode());assertThat(result.getErrorCode()).isEqualTo("PROVIDER_NOT_CONFIGURED");assertThat(result.getData()).isNull();}private ToolDefinition tool(){return new ToolDefinition("t","v","search",1,"search",ToolProtocol.EXTERNAL_SEARCH,"{}","{}",ToolRiskLevel.LOW,false,false,1000,"{}",Collections.emptyList(),"{}",true);}private ExecutionContext context(){return new ExecutionContext("t","w","u","s",null,"r","a",1,"zh","UTC",Collections.emptyList(),Collections.emptyList(),new AuthorizationContext(Collections.emptySet()),ExecutionBudget.defaults(),Instant.now().plusSeconds(10),Collections.emptyMap(),"trace");}}
